from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_COLOR_INDEX
import re
d=Document()
for s in d.sections: s.left_margin=Inches(1.25); s.right_margin=Inches(1); s.top_margin=s.bottom_margin=Inches(1)
d.styles['Normal'].font.name='Times New Roman'; d.styles['Normal'].font.size=Pt(12)
for h,z in(('Heading 1',16),('Heading 2',14)): d.styles[h].font.name='Times New Roman'; d.styles[h].font.size=Pt(z); d.styles[h].font.color.rgb=RGBColor(0,0,0)
def P(t,b=False,c=False,sz=None,style=None):
    p=d.add_paragraph(style=style); p.paragraph_format.line_spacing=1.5; p.alignment=WD_ALIGN_PARAGRAPH.CENTER if c else WD_ALIGN_PARAGRAPH.JUSTIFY
    for part in re.split(r'(\[\[.*?\]\])',t):
        if part.startswith('[['): r=p.add_run('['+part[2:-2]+']'); r.font.highlight_color=WD_COLOR_INDEX.YELLOW
        else: r=p.add_run(part)
        r.bold=b
        if sz: r.font.size=Pt(sz)
def B(l):
    for i in l: P(i,style='List Bullet')
def IMG(p,cap,w=5.6): d.add_picture(p,width=Inches(w)); d.paragraphs[-1].alignment=WD_ALIGN_PARAGRAPH.CENTER; P(cap,c=True,sz=10)
def T(rows):
    t=d.add_table(rows=len(rows),cols=len(rows[0])); t.style='Table Grid'
    for i,r in enumerate(rows):
        for j,v in enumerate(r): x=t.cell(i,j); x.text=''; run=x.paragraphs[0].add_run(str(v)); run.font.size=Pt(10); run.bold=(i==0)
    d.add_paragraph()
PB=d.add_page_break; H=d.add_heading
P('FIELD PROJECT REPORT',True,True,20); P('(Course Code: CA-310 | Field Project | FP-2)',c=True); P('on',c=True); P('SpareGo',True,True,26)
P('Spare Parts Order and Delivery Management System for Local Auto-Spare-Parts Shops',True,True,14); P('Submitted by',c=True); P('[[Student name(s) and roll number(s)]]',c=True)
P('Under the guidance of',c=True); P('[[Guide name]]',c=True); P('[[Class, Department, College, University, Academic year]]',c=True); PB()
P('CERTIFICATE (College / Mentor)',True,True,14); P('This is to certify that the Field Project "SpareGo – Spare Parts Order and Delivery Management System" was carried out by [[names]] during the academic year [[year]] under my guidance.'); P('\n\nGuide: ____________     HOD: ____________     Principal: ____________'); PB()
P('ORGANIZATION CERTIFICATE',True,True,14); P('[[Paste the signed certificate from the spare parts shop where the field study was done: shop name, address, owner signature and stamp.]]'); PB()
P('ACKNOWLEDGEMENT',True,True,14); P('We thank our guide [[name]], the owner of [[shop name]] for allowing the study and sharing honest feedback, our HOD, faculty and family.'); PB()
P('CONTENTS',True,True,14)
for l in ['Chapter 1: Introduction','Chapter 2: Problem Identification and Feasibility Study','Chapter 3: Requirement Analysis','Chapter 4: System Design','Chapter 5: Implementation','Chapter 6: Conclusion and Future Scope','Appendix A: Questionnaire | Appendix B: Test Cases | References']: P(l)
PB()
H('Chapter 1: Introduction',1); H('1.1 Background of the Project',2)
P('Local auto-spare-parts shops serve mechanics, garages and vehicle owners. Customers usually phone or visit the shop, ask for a part by vehicle model, and the shop sends it by a delivery boy. Orders are noted on paper or WhatsApp, availability is checked by searching shelves, and customers repeatedly call to ask "where is my part?". Wrong parts, lost orders and wasted time are common, and a mechanic waiting for a part loses working hours.')
P('SpareGo is a web application that digitises this workflow: parts catalogue searchable by vehicle model, stock tracking with low-stock alerts, order placement with automatic invoice, packing and rider assignment, a public tracking page for customers, and OTP-verified delivery.')
H('1.2 Objectives of the Project',2)
B(['To study the existing manual order and delivery process of a spare parts shop through field visit, interviews, observation and questionnaires.','To identify the problems and define functional and non-functional requirements.','To design the system using DFD, ERD, use case, flowchart and database schema.','To develop a working application using Python, Flask and SQLite.','To add smart features: search by vehicle model, low-stock alerts, order tracking link on WhatsApp, delivery OTP and rider performance report.','To test the system manually and compare the existing and proposed systems.'])
H('1.3 Scope',2); P('Single shop, one owner/staff login, in-house riders. Online payment, GPS tracking and multi-shop support are future scope.'); PB()
H('Chapter 2: Problem Identification and Feasibility Study',1); H('2.1 Description of the Current System',2)
P('The field study was done at [[shop name, address]] on [[dates]]. Owner: [[name]]; years in business: [[years]]; number of delivery boys: [[n]]; approximate orders per day: [[n]]. The current process is:')
B(['Customer phones or visits and asks for a part by vehicle and part name.','Owner or helper searches shelves/memory; availability is told verbally.','Order is written in a notebook or WhatsApp chat; bill is hand-written.','A delivery boy is told verbally; the customer calls to ask about delivery status.','Payment collection and delivery proof are not recorded.'])
P('[[Write 1–2 paragraphs in your own words about what you actually observed.]]')
H('2.2 Limitations of the Existing System',2)
T([['No.','Problem','Impact'],['1','No searchable catalogue by vehicle model','Slow response, wrong part given'],['2','Stock checked by memory','Out-of-stock found late; lost sales'],['3','Orders on paper / WhatsApp','Lost or forgotten orders'],['4','No order status for customer','Repeated calls to shop'],['5','No delivery proof','Disputes about delivery and payment'],['6','No rider or sales reports','Owner cannot measure performance']])
P('[[Confirm/replace this table with your real survey findings.]]')
H('2.3 Feasibility Study',2)
T([['Type','Assessment'],['Technical','Free tools (Python, Flask, SQLite); runs on any PC; customer needs only a phone browser. Feasible.'],['Economic','No licence cost. Feasible.'],['Operational','Few screens, simple steps; owner confirmed he can use it [[confirm in interview]]. Feasible.'],['Schedule','Completed within the 60-hour project period. Feasible.']]); PB()
H('Chapter 3: Requirement Analysis',1)
H('3.1 Method of Data Collection',2); P('Primary data was collected through field visit, interview, questionnaire and observation. The questionnaire is in Appendix A.')
H('3.2 Field Visit Details',2); T([['Visit','Date','Place','Purpose'],['1','[[date]]','[[shop]]','Introduce project, observe order and delivery process'],['2','[[date]]','[[shop]]','Interview owner, collect questionnaires'],['3','[[date]]','[[shop]]','Demonstrate prototype and take feedback']])
H('3.3 Interview Details',2); P('Interviewee: [[owner name]]. Duration: [[minutes]]. Main points: [[real answers about order volume, delivery delays, wrong-part returns, how customers ask for status]].')
H('3.4 Questionnaire / Survey Method',2); P('A 10-question questionnaire was given to [[N]] respondents ([[shop owners, mechanics, customers]]).')
H('3.5 Observation Details',2); P('We observed the shop for [[hours]] on [[days]] and noted how orders were taken, how long search took and how delivery was handled. [[Write real observations.]]')
H('3.6 Summary of Collected Data',2); T([['Question','Result (fill from your survey)'],['Customers who call to ask delivery status','[[x of N]]'],['Orders delivered late / wrong part sent','[[x of N]]'],['Orders recorded on paper/WhatsApp only','[[x of N]]'],['Would like order tracking link','[[x of N]]'],['Willing to use an app for orders','[[x of N]]']]); P('NOTE: Numbers must come from the real survey; do not invent them.',True)
H('3.7 Functional Requirements',2)
B(['FR1: Secure shop login.','FR2: Add parts with vehicle model, price, stock; search by part/brand/vehicle; restock.','FR3: Add customers (individual/mechanic/garage) and riders.','FR4: Place order with stock check; stock reduces automatically; delivery fee rule (free above Rs 1000).','FR5: Order life cycle: Placed → Packed → Out for Delivery → Delivered.','FR6: Rider must be assigned before dispatch.','FR7: Delivery completes only with correct customer OTP.','FR8: Public tracking page (order number + phone) and WhatsApp tracking link.','FR9: Printable invoice.','FR10: Dashboard, low-stock alerts, most-ordered parts, rider performance and 7-day order value.'])
H('3.8 Non-Functional Requirements',2); B(['Usability: simple pages; tracking page is mobile friendly.','Performance: page loads in under 1 second for small data.','Reliability: foreign keys and CHECK constraints; invalid input rejected.','Security: hashed passwords, login protection, OTP for delivery, tracking needs phone match.','Portability: runs on any OS with Python.'])
PB()
H('Chapter 4: System Design',1)
H('4.1 Use Case Diagram',2); IMG('docs/usecase.png','Figure 4.1: Use case diagram')
H('4.2 Flowchart',2); IMG('docs/flow.png','Figure 4.2: Order and delivery flowchart',4.6)
H('4.3 Data Flow Diagrams',2); IMG('docs/dfd0.png','Figure 4.3: DFD Level 0'); IMG('docs/dfd1.png','Figure 4.4: DFD Level 1')
H('4.4 Entity Relationship Diagram',2); IMG('docs/erd.png','Figure 4.5: ER diagram')
H('4.5 Database Design',2)
T([['Table','Columns','Keys / constraints'],['users','id, username, password_hash, shop_name','PK id; username UNIQUE'],['parts','id, name, brand, vehicle, price, stock, min_stock','PK id; price>=0, stock>=0'],['customers','id, name, phone, kind, address','PK id'],['riders','id, name, phone, active','PK id'],['orders','id, customer_id, rider_id, address, status, otp, delivery_fee, total, created/packed/out/delivered_at','PK id; FK customer_id, rider_id'],['order_items','id, order_id, part_id, qty, price','PK id; FK order_id, part_id']])
P('Tables are in third normal form. The unit price is copied into order_items so old invoices do not change when part prices change.')
H('4.6 Business Rules',2); B(['Delivery fee Rs 40; free if subtotal is Rs 1000 or more.','Order cannot be placed if quantity exceeds stock.','Status can only move forward one step at a time.','Rider is mandatory before Out for Delivery; correct OTP is mandatory for Delivered.','Low-stock alert when stock is less than or equal to minimum stock.'])
PB()
H('Chapter 5: Implementation',1)
H('5.1 Technologies Used',2); T([['Component','Technology'],['Language','Python 3'],['Framework','Flask with Jinja2'],['Database','SQLite'],['Front end','HTML5, CSS3 (offline)'],['Security','Werkzeug hashing, Flask sessions'],['Tools','VS Code, Git/GitHub, Playwright, Graphviz']])
H('5.2 Description of Modules',2); T([['Module','Description'],['Authentication','Login/logout, session protection'],['Parts & Stock','Catalogue, search by vehicle, restock, low-stock'],['Customers & Riders','Master data, rider workload and history'],['Orders','Order creation, stock deduction, fee, invoice'],['Delivery & OTP','Pack, assign rider, dispatch, OTP-confirmed delivery'],['Tracking','Public tracking page and WhatsApp link'],['Reports','Dashboard, top parts, rider performance, 7-day value']])
H('5.3 Application Screenshots',2)
for n,cap in [('login','Login'),('dashboard','Dashboard'),('parts','Parts catalogue and search'),('new_order','New order'),('orders','Order list'),('order_detail','Order detail, invoice and WhatsApp link'),('riders','Riders'),('reports','Reports')]: IMG(f'docs/screenshots/{n}.png',f'Figure: {cap}',5.8)
IMG('docs/screenshots/track_mobile.png','Figure: Customer tracking page (mobile view)',2.6)
P('NOTE: Screenshots use demo data. Replace them with real-data screenshots before submission.',True); PB()
H('Chapter 6: Conclusion and Future Scope',1); H('6.1 Conclusion',2)
P('SpareGo replaces paper and WhatsApp-based ordering with a structured system that finds parts by vehicle model, prevents over-selling, tracks every order and proves delivery with an OTP. All 16 test cases passed. [[Add the owner\'s real feedback after the demo.]]')
H('6.2 Existing vs Proposed System',2); T([['Feature','Existing','SpareGo'],['Part search','Memory / shelves','Search by part, brand, vehicle'],['Order record','Notebook / chat','Database with invoice'],['Status for customer','Phone calls','Tracking link / page'],['Delivery proof','None','OTP verification'],['Stock alert','None','Low-stock alerts'],['Reports','None','Auto reports and rider performance']])
H('6.3 Future Scope',2); B(['Live GPS tracking of riders and ETA.','Rider mobile app.','Online payment / UPI link and COD reconciliation.','Barcode scanning, supplier purchase orders.','Multi-shop and staff roles, Hindi/Marathi interface.','Demand prediction from order history.']); PB()
H('Appendix A: Questionnaire',1)
for i,q in enumerate(['What type of customer are you? Mechanic / Garage / Individual','How do you order spare parts now? Visit / Phone / WhatsApp','How long does it take to know if a part is available?','Have you received a wrong or incompatible part? Yes / No','How long does delivery usually take?','Do you have to call to ask where your order is? Yes / No','Is delivery ever late enough to affect your work? Yes / No','Would you like a tracking link on WhatsApp? Yes / No','Would you prefer to confirm delivery using an OTP? Yes / No','Would you use a simple app for ordering parts? Yes / No'],1): P(f'Q{i}. {q}')
H('Appendix B: Manual Test Cases',1)
T([['ID','Test case','Expected','Result'],['TC01','Wrong password','Error shown','Pass'],['TC02','Valid login','Dashboard opens','Pass'],['TC03','Add part','Part listed','Pass'],['TC04','Invalid phone','Rejected; valid saved','Pass'],['TC05','Add rider','Rider listed','Pass'],['TC06','Order qty above stock','Rejected','Pass'],['TC07','Order 2 x Rs 300','Total 640 (incl. fee 40); stock 10→8','Pass'],['TC08','Fee rule','Free at 1000+, else 40','Pass'],['TC09','Mark packed','Status PACKED','Pass'],['TC10','Dispatch without rider','Blocked','Pass'],['TC11','Assign rider, dispatch','OUT FOR DELIVERY','Pass'],['TC12','Wrong OTP','Not delivered','Pass'],['TC13','Correct OTP','DELIVERED','Pass'],['TC14','Public tracking','Status visible without login','Pass'],['TC15','Tracking wrong phone','Not found','Pass'],['TC16','Admin page without login','Redirect to login','Pass']])
H('References',1); B(['Flask documentation – https://flask.palletsprojects.com','SQLite documentation – https://www.sqlite.org/docs.html','Pressman R., Software Engineering: A Practitioner\'s Approach.','Kendall & Kendall, Systems Analysis and Design.'])
